                entry("bard", "Bard", "Inspiring Charisma full spellcaster and jack of all trades (d8 hit die).", "Primary: Charisma. Saves: Dexterity, Charisma. Armor: Light. Weapons: Simple. Core features: Bardic Inspiration (Bonus Action die to ally D20 Test), Spellcasting (Charisma), Expertise, Jack of All Trades (half proficiency to non-proficient ability checks), Font of Inspiration.", hit_die=8, primary_abilities=["charisma"], saving_throws=["dexterity", "charisma"], subclass_level=3, level_1_features=["bardic_inspiration", "spellcasting"]),
                entry("cleric", "Cleric", "Armored Wisdom full spellcaster wielding divine magic and Channel Divinity (d8 hit die).", "Primary: Wisdom. Saves: Wisdom, Charisma. Armor: Light, Medium, Shields. Weapons: Simple. Core features: Spellcasting (Wisdom), Divine Order (Protector or Thaumaturge), Channel Divinity (Divine Spark / Turn Undead), Sear Undead, Blessed Strikes, Divine Intervention.", hit_die=8, primary_abilities=["wisdom"], saving_throws=["wisdom", "charisma"], subclass_level=3, level_1_features=["spellcasting", "divine_order"]),
                entry("druid", "Druid", "Nature Wisdom full spellcaster able to transform via Wild Shape (d8 hit die).", "Primary: Wisdom. Saves: Intelligence, Wisdom. Armor: Light, Shields. Weapons: Simple. Core features: Spellcasting (Wisdom), Druidic, Primal Order (Magician or Warden), Wild Shape (Bonus Action beast forms + Temp HP), Wild Companion, Elemental Fury.", hit_die=8, primary_abilities=["wisdom"], saving_throws=["intelligence", "wisdom"], subclass_level=3, level_1_features=["spellcasting", "druidic", "primal_order"]),
