                entry("paladin", "Paladin", "Oath-bound warrior combining heavy armor, Lay on Hands, Auras, and Smites (d10 hit die).", "Primary: Strength, Charisma. Saves: Wisdom, Charisma. Armor: Light, Medium, Heavy, Shields. Weapons: Simple, Martial. Core features: Lay on Hands (5 * level HP pool, Bonus Action heal or cure Poisoned), Spellcasting (Charisma, half caster from level 1), Weapon Mastery, Paladin's Smite (Divine Smite always prepared), Fighting Style, Channel Divinity, Extra Attack, Aura of Protection (+Cha mod to saves within 10/30 ft).", hit_die=10, primary_abilities=["strength", "charisma"], saving_throws=["wisdom", "charisma"], subclass_level=3, level_1_features=["lay_on_hands", "spellcasting", "weapon_mastery"]),
