                entry("sorcerer", "Sorcerer", "Innate Charisma full spellcaster reshaping spells with Metamagic (d6 hit die).", "Primary: Charisma. Saves: Constitution, Charisma. Armor: None. Weapons: Simple. Core features: Spellcasting (Charisma), Innate Sorcery (Bonus Action +1 spell save DC and Advantage on sorcerer spell attacks for 1 minute), Font of Magic (Sorcery Points), Metamagic, Sorcerous Restoration.", hit_die=6, primary_abilities=["charisma"], saving_throws=["constitution", "charisma"], subclass_level=3, level_1_features=["spellcasting", "innate_sorcery"]),
