                entry("piercing", "Piercing", "Puncturing and impaling damage from spears, arrows, fangs, and daggers.", "Physical puncture damage from arrows, spears, rapiers, and bites."),
                entry("slashing", "Slashing", "Cutting and cleaving damage from swords, axes, and claws.", "Physical cutting damage from blades, axes, and talons."),
                entry("acid", "Acid", "Corrosive chemical dissolution.", "Corrosive burns from acid sprays, black dragon breath, or oozes."),
                entry("cold", "Cold", "Freezing numbness and frostbite.", "Infernal ice, arctic exposure, and frost magic."),
                entry("fire", "Fire", "Flames, scorching heat, and burning hazards.", "Flames, magma, burning oil, and fire spells; ignites flammable unattended objects."),
                entry("force", "Force", "Pure magical energy focused into damaging form.", "Pure arcane impact such as Magic Missile or Eldritch Blast; rarely resisted."),
                entry("lightning", "Lightning", "Electrical arcs and thunderbolts.", "Electrical shock from lightning bolts and storm creatures."),
                entry("necrotic", "Necrotic", "Withering decay that saps life force.", "Life-draining decay wielded by undead and necromantic magic."),
                entry("poison", "Poison", "Venoms, toxins, and noxious fumes.", "Biological toxins; objects, constructs, and most undead are immune."),
                entry("psychic", "Psychic", "Mental assault directly against a mind.", "Telepathic trauma; objects and mindless constructs are immune."),
